import{z as l,x as s,o as t,c as d,q as A,j as B,D as n,d as e,s as r,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"速率单调","description":"","frontmatter":{"title":"速率单调","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rate-monotonic.md","filePath":"cs/rate-monotonic.md","lastUpdated":1791063341000}'),p={name:"cs/rate-monotonic.md"};function m(D,a,u,C,_,c){const i=s("Mermaid");return t(),d("div",null,[a[2]||(a[2]=A('<h1 id="速率单调" tabindex="-1">速率单调 <a class="header-anchor" href="#速率单调" aria-label="Permalink to &quot;速率单调&quot;">​</a></h1><div class="epigraph"><p>周期越短优先级越高：在独立、可抢占、截止等于周期的假设下，利用率不超过 $n(2^{1/n}-1)$ 则速率单调可调度。</p><footer>—— 据 Liu and Layland, Scheduling Algorithms for Multiprogramming in a Hard-Real-Time Environment, JACM 1973</footer></div><p><a href="/cs/realtime-sched">上一课</a>对照了公平份额与期限，并点名 RM 与 EDF。缺口是把 <strong>RM</strong> 收成可检查的规则：静态优先级按周期（速率）指定，短周期高优先级，以及 Liu–Layland 利用率界限。本课不把响应时间分析（RTA）的迭代公式写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一组周期任务 \\(\\tau_i=(C_i,P_i)\\)，\\(D_i=P_i\\)，独立、可抢占、无锁。要不要在运行时比较截止？RM 说不必：离线按 \\(P_i\\) 排序即可。缺口不是再定义硬实时，而是这条静态赋值以及充分条件 \\(\\sum C_i/P_i \\le n(2^{1/n}-1)\\)（\\(n\\to\\infty\\) 时约 \\(0.69\\)）。超界仍可能可调度，那是充分非必要。</p><p><span class="marginnote">数字实例：界限随任务数变化。\\(n=1\\) 时 \\(2^{1}-1=1\\)（单任务可跑到 100%）；\\(n=2\\) 时 \\(2(\\sqrt2-1)\\approx 0.83\\)；\\(n=3\\) 时约 \\(0.78\\)；\\(n=10\\) 时约 \\(0.70\\)。也就是说任务越多，这个「闭眼判可调度」的门槛越低，但永远不低于约 69%。</span></p><p><span class="marginnote">调和周期（一个周期是另一个的整数倍）时界限可放到 1。教学先记一般界限，再承认特例更宽。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>指定优先级： \\(P_i\\lt P_j \\Rightarrow \\tau_i\\) 高于 \\(\\tau_j\\)。运行：总是跑当前最高优先级的就绪周期任务，与<a href="/cs/runqueue">运行队列</a>的优先级槽一致。利用率测试作快速拒绝；要精确可用关键瞬间：所有任务同时释放时的最坏。本课不把关键瞬间证明展开。</p>',9)),(t(),B(o,null,{default:n(()=>[r(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%91%A8%E6%9C%9F%E4%BB%BB%E5%8A%A1%E9%9B%86%22%5D%20--%3E%20PRI%5B%22%E7%9F%AD%E5%91%A8%E6%9C%9F%20%3D%20%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%22%5D%0A%20%20PRI%20--%3E%20TEST%5B%22%E5%88%A9%E7%94%A8%E7%8E%87%E5%85%85%E5%88%86%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20TEST%20--%3E%20RUN%5B%22%E9%9D%99%E6%80%81%E4%BC%98%E5%85%88%E7%BA%A7%E6%8A%A2%E5%8D%A0%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与 CFS 并存时，RM 队列必须先于公平队列，对照课已说。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"常见误区：初学者容易把「利用率超过 \\(n(2^{1/n}-1)\\)」读成「必然错过截止」。界限只是充分条件——它是快速拒绝用的筛子，筛不掉不代表过不了精确分析。两个周期 10ms、执行 6ms 的任务利用率 1.2 当然不行，但 0.8 的任务集也完全可能 RM 可调度。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,[e("RM 最优在「静态优先级」类中（Liu–Layland 假设下）：若某静态赋值可调度，则 RM 也可。它不处理共享锁的反转——那要用"),E("a",{href:"/cs/pi-pcp"},"PI"),e("。切换税与 ISR 必须打进 \\(C_i\\)，否则纸上可调度、板上逾期。这把内核抢占与中断线程化接到期限上。")],-1)),(t(),B(o,null,{default:n(()=>[r(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%85%B3%E9%94%AE%E7%9E%AC%E9%97%B4%EF%BC%9At%3D0%20%E5%85%A8%E9%83%A8%E4%BB%BB%E5%8A%A1%E5%90%8C%E6%97%B6%E9%87%8A%E6%94%BE%22%5D%20--%3E%20H%5B%22%E9%AB%98%E9%A2%91%E4%BB%BB%E5%8A%A1%E5%85%88%E8%B7%91%E5%AE%8C%EF%BC%9A%E7%9F%AD%E5%91%A8%E6%9C%9F%E6%9C%80%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%22%5D%0A%20%20H%20--%3E%20M%5B%22%E4%B8%AD%E9%A2%91%E4%BB%BB%E5%8A%A1%E8%BF%90%E8%A1%8C%E4%B8%AD%22%5D%0A%20%20M%20--%3E%20L%5B%22%E4%BD%8E%E9%A2%91%E4%BB%BB%E5%8A%A1%E5%8F%AA%E6%8A%A2%E5%88%B0%E9%9B%B6%E7%A2%8E%E6%97%B6%E9%97%B4%22%5D%0A%20%20L%20--%3E%20Q%7B%22%E4%BD%8E%E9%A2%91%E6%88%AA%E6%AD%A2%E6%98%AF%E5%90%A6%E8%B5%B6%E4%B8%8A%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E7%BA%B8%E9%9D%A2%20C_i%20%E4%B8%8D%E5%90%AB%E4%B8%AD%E6%96%AD%22%7C%20A%5B%22%E6%BC%8F%E7%AE%97%202ms%EF%BC%9A%E9%80%BE%E6%9C%9F%EF%BC%8C%E6%9D%BF%E4%B8%8A%E7%BF%BB%E8%BD%A6%22%5D%0A%20%20Q%20--%3E%7C%22C_i%20%E5%B7%B2%E5%90%AB%E5%88%87%E6%8D%A2%E7%A8%8E%E4%B8%8E%20ISR%22%7C%20B%5B%22%E5%8F%AF%E8%B0%83%E5%BA%A6%E7%BB%93%E8%AE%BA%E6%88%90%E7%AB%8B%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p><span class="marginnote">为什么重要：这一步做错了，后面整个静态分析都会作废。设每毫秒来一次 20 微秒的中断，若不把它摊进各任务的 \\(C_i\\)，10ms 周期的任务一个周期就凭空多担 0.2ms——利用率被系统性低估，样机不忙、量产超期。实时工程的第一课是：测到的执行时间必须含税。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把偶发任务、前馈抖动写成完整 Sporadic Server。也不声称桌面 Linux 的 <code>SCHED_FIFO</code> 自动等于 RM：那只是固定优先级，周期要用户自己对齐。EDF 的动态截止与界限 1 是下一课。</p><p>后课默认：静态期限调度用 RM。若允许运行时谁更急谁跑，下一课 EDF。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RM：周期越短优先级越高；利用率 \\(n(2^{1/n}-1)\\) 是充分条件。</li><li>静态类中最优（经典假设下）；锁与 ISR 另计。</li><li>动态最早截止是下一课。</li><li>出处：Liu and Layland, <em>JACM</em> 1973。</li></ul>',6))])}const F=l(p,[["render",m]]);export{f as __pageData,F as default};
